pub(crate) const UAT_PGBIT: usize = 14;
/// UAT page size.
pub(crate) const UAT_PGSZ: usize = 1 << UAT_PGBIT;
/// UAT page offset mask.
pub(crate) const UAT_PGMSK: usize = UAT_PGSZ - 1;

type Pte = AtomicU64;

const PTE_BIT: usize = 3; // log2(sizeof(Pte))
const PTE_SIZE: usize = 1 << PTE_BIT;

/// Number of PTEs per page.
const UAT_NPTE: usize = UAT_PGSZ / size_of::<Pte>();

/// Number of address bits to address a level
const UAT_LVBIT: usize = UAT_PGBIT - PTE_BIT;
/// Number of entries per level
const UAT_LVSZ: usize = UAT_NPTE;
/// Mask of level bits
const UAT_LVMSK: u64 = (UAT_LVSZ - 1) as u64;

const UAT_LEVELS: usize = 3;

/// UAT input address space
pub(crate) const UAT_IAS: usize = 39;

/* TTBR0 belongs to the broker, and can contain only the exact low alias's
 * slot 0. Retained TTBR1 owns only slot 2; never walk its private slots. */
static int check_tables(struct hv_agx_retained_root *c)
{
    unsigned int i, half;
    APPLE_AGX_UAT_PAGE *root0;
    unsigned long long slots[2];
    unsigned char referenced[HV_AGX_RETAINED_MAX_PAGES] = {0};
    if (c->Tainted || (c->PrefixSaved && !hv_agx_retained_prefix_unchanged(c)))
        return HV_AGX_RETAINED_TAINTED;
    if (c->Roots.Ttbr1PhysicalAddress != c->RetainedPa)
        goto tainted;
    root0 = owned_child(c, c->Roots.Ttbr0PhysicalAddress | 3ULL, 0);
    if (!root0)
        goto tainted;
    for (i = 1; i < 2048; ++i)
        if (root0->Entries[i])
            goto tainted;
    for (i = 3; i < 2048; ++i)
        if (c->RetainedEntries[i])
            goto tainted;
